        for st in sf['top_10']['total_funding'][:10]:
            body += f'\n  <tr><td>{esc(st.get("state",""))}</td><td class="num">${st.get("total_income",0):,}</td><td class="num">${st.get("total_income_per_capita",0):.2f}</td></tr>'
